// features/lifecycle.feature: Approving the replacement approves a vendor whose other documents were already approved
import { expect, expectStatus, test } from "../../fixtures";
import type { Document, Extraction, Vendor } from "../../fixtures";

test(
  "approving the replacement w9 approves a vendor whose other documents were already approved",
  { tag: "@LIF-06" },
  async ({ factory, apiAs }) => {
    // Arrange: a vendor in review, other documents approved, w9 rejected, replaced, and resubmitted
    const member = await apiAs("member");
    const reviewer = await apiAs("reviewer");
    const { vendor, extractions } = await factory.vendorInReview();
    await expectStatus(
      await reviewer.post(`/api/extractions/${extractions.insurance_certificate.id}/decision`, {
        data: { decision: "approve" },
      }),
      200,
    );
    await expectStatus(
      await reviewer.post(`/api/extractions/${extractions.contract.id}/decision`, { data: { decision: "approve" } }),
      200,
    );
    await expectStatus(
      await reviewer.post(`/api/extractions/${extractions.w9.id}/decision`, {
        data: { decision: "reject", note: "Tax ID does not match" },
      }),
      200,
    );
    const replacement = await factory.upload(vendor.id, "w9");
    await expect
      .poll(
        async () => (await expectStatus<Document>(await member.get(`/api/documents/${replacement.id}`), 200)).status,
        { message: "replacement w9 finishes extraction", timeout: 30_000 },
      )
      .toBe("extracted");
    await expectStatus<Vendor>(await member.post(`/api/vendors/${vendor.id}/submit`), 200);
    const replacementExtraction = await factory.extraction(replacement.id);
    expect(replacementExtraction.status, "replacement w9 awaits review").toBe("pending_review");

    // Act
    const decision = await reviewer.post(`/api/extractions/${replacementExtraction.id}/decision`, {
      data: { decision: "approve" },
    });

    // Assert
    const decided = await expectStatus<Extraction>(decision, 200);
    expect(decided.status).toBe("approved");
    const stored = await expectStatus<Vendor>(await reviewer.get(`/api/vendors/${vendor.id}`), 200);
    expect(stored.status).toBe("approved");
    const audit = await expectStatus<{ items: { action: string }[] }>(
      await reviewer.get(`/api/vendors/${vendor.id}/audit`),
      200,
    );
    expect(audit.items.map((e) => e.action)).toContain("vendor.approved");
  },
);
